class LmdbLegacySemiAntiReentrantCommitTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void reentrantCommitInsideSemiAntiObservationRejectsOldEvidence(
			@TempDir(cleanup = CleanupMode.NEVER) Path path) throws Exception {
		run(path, true);
	}

	@Test
	void currentSemiAntiObservationStillLearns(@TempDir(cleanup = CleanupMode.NEVER) Path path) throws Exception {
		run(path, false);
	}

	@Test
	void failedSemiAntiCallbackCannotExposePartialEvidence(@TempDir(cleanup = CleanupMode.NEVER) Path path)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setBackgroundRawSamplingEnabled(false);
		config.setExperimentalQueryOptimizations(true);
		LmdbStore store = new LmdbStore(path.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			statistics.bindExecutionSnapshot(OptionalLong.of(statistics.estimatorRuntime().snapshotVersion()));
			CommitFilter observed = filter();
			observed.provider = statistics.estimatorRuntime().feedback();
			AtomicBoolean failed = new AtomicBoolean();
			observed.beforeFrontierRead = () -> {
				failed.set(true);
				throw new IllegalStateException("injected callback failure after semi/anti update");
			};
			assertThrows(IllegalStateException.class, () -> statistics.recordSemiAntiOutcome(observed, observation()));
			assertTrue(failed.get(), "the callback fails after the semi/anti cell was updated");
			assertNull(statistics.estimatorRuntime().semiAntiFeedback(filter(), "NOT_EXISTS", "memoized-correlated"),
					"an interrupted semi/anti publication cannot expose a partial sample");
		} finally {
			repository.shutDown();
		}
	}

	private static void run(Path path, boolean commit) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setBackgroundRawSamplingEnabled(false);
		config.setExperimentalQueryOptimizations(true);
		LmdbStore store = new LmdbStore(path.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			long revision = statistics.estimatorRuntime().snapshotVersion();
			statistics.bindExecutionSnapshot(OptionalLong.of(revision));
			CommitFilter observed = filter();
			AtomicBoolean committed = new AtomicBoolean();
			observed.provider = statistics.estimatorRuntime().feedback();
			if (commit) {
				observed.beforeConditionRead = () -> {
					try (var connection = repository.getConnection()) {
						connection.add(VF.createIRI("urn:semi-reentrant:new"), VF.createIRI("urn:semi-reentrant:p"),
								VF.createIRI("urn:semi-reentrant:value"));
					}
					committed.set(true);
				};
			}
			statistics.recordSemiAntiOutcome(observed, observation());
			LmdbEvaluationStatistics current = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			var estimate = current.estimatorRuntime().semiAntiFeedback(filter(), "NOT_EXISTS", "memoized-correlated");
			if (commit) {
				assertTrue(committed.get(), "the real commit occurs while the operator provider monitor is held");
				assertNotEquals(revision, current.estimatorRuntime().snapshotVersion());
				assertNull(estimate, "a semi/anti observation from the old snapshot cannot teach the committed store");
			} else {
				assertNotNull(estimate, "a current completed semi/anti observation remains learnable");
			}
		} finally {
			repository.shutDown();
		}
	}

	private static CommitFilter filter() {
		TupleExpr query = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { ?s <urn:semi-reentrant:p> ?o . FILTER NOT EXISTS { ?s <urn:semi-reentrant:q> ?v } }",
				null).getTupleExpr();
		Filter[] result = new Filter[1];
		query.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				if (result[0] == null) {
					result[0] = filter;
				}
				super.meet(filter);
			}
		});
		CommitFilter copy = new CommitFilter(result[0].getArg().clone(), result[0].getCondition().clone());
		PlanningGraphDomains.capture(copy, PlanningGraphDomain.defaultGraph());
		return copy;
	}

	private static EvaluationStatistics.SemiAntiOutcomeObservation observation() {
		return new EvaluationStatistics.SemiAntiOutcomeObservation("NOT_EXISTS", "memoized-correlated",
				"memoized-correlated", 10L, 6L, 4L, 4L, 2L, 2L, 6L, 18L, 4L, 4L, 0L, 0L, 10L, true, "", "");
	}

	private static final class CommitFilter extends Filter {
		private Runnable beforeConditionRead;
		private Runnable beforeFrontierRead;
		private LmdbOperatorFeedbackStats provider;

		CommitFilter(TupleExpr arg, ValueExpr condition) {
			super(arg, condition);
		}

		@Override
		public ValueExpr getCondition() {
			Runnable before = beforeConditionRead;
			if (before != null && provider != null && Thread.holdsLock(provider)) {
				beforeConditionRead = null;
				before.run();
			}
			return super.getCondition();
		}

		@Override
		public String getStringMetricPlanned(String key) {
			Runnable before = beforeFrontierRead;
			if (before != null && provider != null && Thread.holdsLock(provider)
					&& "optimizer.frontierLearningKey".equals(key)) {
				beforeFrontierRead = null;
				before.run();
			}
			return super.getStringMetricPlanned(key);
		}
	}
}
